     1	import type { TrueForgeApi } from "@truefoundry/trueforge-sdk";
     2	
     3	/**
     4	 * Pure timeline logic for the case file UI. Maps live harness events onto the
     5	 * eight protocol stages from skills/rarecase-debugging/SKILL.md and coalesces
     6	 * chatty token streams into stable entries. No React here, so the mapping is
     7	 * unit-testable on its own.
     8	 */
     9	
    10	export const STAGES = [
    11	  "Evidence",
    12	  "Hypothesis",
    13	  "Reproduction",
    14	  "Diagnosis",
    15	  "Patch",
    16	  "Verification",
    17	  "Approval",
    18	  "Receipt",
    19	] as const;
    20	
    21	export type Stage = (typeof STAGES)[number];
    22	
    23	export interface TimelineEntry {
    24	  /** Stable identity: coalesced updates replace the entry instead of appending. */
    25	  key: string;
    26	  /** The protocol stage this belongs to, or null for the raw event log. */
    27	  stage: Stage | null;
    28	  kind: "message" | "event";
    29	  title: string;
    30	  text: string;
    31	}
    32	
    33	/**
    34	 * Only events with an honest home in the protocol land on a stage. Assistant
    35	 * narration spans every stage at once, and lifecycle chatter belongs to none,
    36	 * so both stay in the raw log rather than being assigned by guesswork.
    37	 */
    38	export function mapEventToStage(event: { type: string }): Stage | null {
    39	  switch (event.type) {
    40	    // SKILL.md stage 3 works in the sandbox.
    41	    case "sandbox.created":
    42	      return "Reproduction";
    43	    // Stage 7 is where the pause becomes a human decision.
    44	    case "tool.approval_required":
    45	      return "Approval";
    46	    // Stage 8 reads back what happened once the turn has ended.
    47	    case "turn.done":
    48	      return "Receipt";
    49	    default:
    50	      return null;
    51	  }
    52	}
    53	
    54	/** Message content arrives as plain text or structured parts; flatten both. */
    55	export function contentToText(content: TrueForgeApi.ModelMessageEvent["content"]): string {
    56	  if (content == null) {
    57	    return "";
    58	  }
    59	  if (typeof content === "string") {
    60	    return content;
    61	  }
    62	  return content
    63	    .map((part) => ("text" in part && typeof part.text === "string" ? part.text : ""))
    64	    .join("");
    65	}
    66	
    67	export function applyTimelineEvent(
    68	  entries: TimelineEntry[],
    69	  event: TrueForgeApi.TurnStreamingEvent,
    70	): TimelineEntry[] {
    71	  if (event.type === "model.message.delta") {
    72	    const key = `msg:${event.id}`;
    73	    const fragment = event.content ?? "";
    74	    const existingIndex = entries.findIndex((entry) => entry.key === key);
    75	    if (existingIndex === -1) {
    76	      return [
    77	        ...entries,
    78	        { key, stage: null, kind: "message", title: "Assistant", text: fragment },
    79	      ];
    80	    }
    81	    const updated = [...entries];
    82	    const existing = updated[existingIndex];
    83	    updated[existingIndex] = { ...existing, text: existing.text + fragment };
    84	    return updated;
    85	  }
    86	
    87	  if (event.type === "model.message") {
    88	    const key = `msg:${event.id}`;
    89	    const next: TimelineEntry = {
    90	      key,
    91	      stage: null,
    92	      kind: "message",
    93	      title: "Assistant",
    94	      text: contentToText(event.content),
    95	    };
    96	    // The transport re-yields a growing message; the longest content wins so
    97	    // either arrival order (base first or deltas first) converges, and the
    98	    // entry keeps its identity so React never mounts one node per token.
    99	    const existingIndex = entries.findIndex((entry) => entry.key === key);
   100	    if (existingIndex === -1) {
   101	      return [...entries, next];
   102	    }
   103	    const updated = [...entries];
   104	    const existing = updated[existingIndex];
   105	    updated[existingIndex] =
   106	      next.text.length >= existing.text.length ? { ...existing, text: next.text } : existing;
   107	    return updated;
   108	  }
   109	
   110	  return [
   111	    ...entries,
   112	    {
   113	      key: `evt:${event.id}`,
   114	      stage: mapEventToStage(event),
   115	      kind: "event",
   116	      title: event.type,
   117	      text: "",
   118	    },
   119	  ];
   120	}
   121	
   122	export interface PendingApproval {
   123	  threadId: string;
   124	  toolCallId: string;
   125	  sourceEventId?: string;
   126	}
   127	
   128	export interface ToolCallSummary {
   129	  name: string;
   130	  server?: string;
   131	  argsJson?: string;
   132	}
   133	
   134	/**
   135	 * The harness routes every MCP call through its own `call_tool` wrapper, so the
   136	 * name on the tool call is always `call_tool` and the action the human is
   137	 * actually being asked to approve sits inside the arguments. Unwrap it, and
   138	 * fall back to the raw call when the envelope is not the expected shape —
   139	 * streamed arguments can still be truncated JSON when a turn ends early.
   140	 */
   141	export function describeToolCall(call: TrueForgeApi.ToolCall): ToolCallSummary {
   142	  const raw = call.function.arguments;
   143	  try {
   144	    const parsed: unknown = JSON.parse(raw);
   145	    if (parsed && typeof parsed === "object" && "tool_name" in parsed) {
   146	      const envelope = parsed as { tool_name?: unknown; mcp_server?: unknown; input?: unknown };
   147	      if (typeof envelope.tool_name === "string") {
   148	        return {
   149	          name: envelope.tool_name,
   150	          server: typeof envelope.mcp_server === "string" ? envelope.mcp_server : undefined,
   151	          argsJson: JSON.stringify(envelope.input ?? {}, null, 2),
   152	        };
   153	      }
   154	    }
   155	  } catch {
   156	    // Not the wrapper, or not finished streaming: show what we do have.
   157	  }
   158	  return { name: call.function.name, argsJson: raw || undefined };
   159	}
   160	
   161	/**
   162	 * A turn that pauses for a human still reports `turn.done`, with the decision
   163	 * it is waiting on listed in `requiredActions`. Treating that as the end of the
   164	 * case would close the approval before it was ever shown.
   165	 */
   166	export function pendingActions(
   167	  event: TrueForgeApi.TurnDoneEvent,
   168	): TrueForgeApi.ActionRequiredEvent[] {
   169	  return "requiredActions" in event.state ? event.state.requiredActions : [];
   170	}
   171	
   172	/** Pulls the decision the human owes out of a pause event, if it is one. */
   173	export function extractApproval(event: TrueForgeApi.TurnStreamingEvent): PendingApproval | null {
   174	  if (event.type !== "tool.approval_required") {
   175	    return null;
   176	  }
   177	  const call = event.toolCalls[0];
   178	  if (!call) {
   179	    return null;
   180	  }
   181	  return {
   182	    threadId: event.threadId,
   183	    toolCallId: call.id,
   184	    sourceEventId: call.sourceEventId,
   185	  };
   186	}
   187	
   188	const PR_URL = /https?:\/\/[^\s)"']+/g;
   189	
   190	export interface CaseReceipt {
   191	  text: string;
   192	  links: string[];
   193	}
   194	
   195	/**
   196	 * The receipt is whatever the final message reports, PR links extracted. A turn
   197	 * can reach a terminal state with no output at all — cancelled, errored, or
   198	 * stopped after a denial — so the caller may supply the last narration it saw
   199	 * rather than close the case on a blank panel.
   200	 */
   201	export function buildReceipt(
   202	  event: TrueForgeApi.TurnDoneEvent,
   203	  fallbackText = "",
   204	): CaseReceipt | null {
   205	  const output = "output" in event.state ? event.state.output : null;
   206	  const text = (contentToText(output?.content ?? null) || fallbackText).trim();
   207	  if (!text) {
   208	    return null;
   209	  }
   210	  return { text, links: text.match(PR_URL) ?? [] };
   211	}
