     3	import { useCallback, useRef, useState } from "react";
     4	import type { TrueForgeApi } from "@truefoundry/trueforge-sdk";
     5	import { ApprovalCard, type ResolvedPending } from "@/components/approval-card";
     6	import {
     7	  applyTimelineEvent,
     8	  buildReceipt,
     9	  contentToText,
    10	  describeToolCall,
    11	  extractApproval,
    12	  pendingActions,
    13	  STAGES,
    14	  type CaseReceipt,
    15	  type TimelineEntry,
    16	} from "@/lib/timeline";
