    18	type StreamEvent =
    19	  | { type: "case.started"; sessionId: string }
    20	  | { type: "stream.error"; error: string }
    21	  | TrueForgeApi.TurnStreamingEvent;
    22	
    23	type Phase = "idle" | "running" | "awaiting" | "done" | "error";
    24	
    25	/**
    26	 * Reads an SSE response body and hands each parsed event to `onEvent`.
    27	 * Frames can split across chunks, so bytes buffer until a full `\n\n` boundary.
    28	 */
    29	async function consumeSse(
    30	  response: Response,
    31	  onEvent: (event: StreamEvent) => void,
    32	): Promise<void> {
    33	  if (!response.ok || !response.body) {
    34	    const problem = (await response.json().catch(() => null)) as { error?: string } | null;
    35	    throw new Error(problem?.error ?? `Request failed with status ${response.status}`);
    36	  }
    37	
    38	  const reader = response.body.getReader();
    39	  const decoder = new TextDecoder();
    40	  let buffer = "";
    41	  try {
    42	    for (;;) {
    43	      const { done, value } = await reader.read();
    44	      if (done) {
    45	        break;
    46	      }
    47	      buffer += decoder.decode(value, { stream: true });
    48	      let boundary = buffer.indexOf("\n\n");
    49	      while (boundary !== -1) {
    50	        const frame = buffer.slice(0, boundary);
    51	        buffer = buffer.slice(boundary + 2);
    52	        if (frame.startsWith("data: ")) {
    53	          onEvent(JSON.parse(frame.slice("data: ".length)) as StreamEvent);
    54	        }
    55	        boundary = buffer.indexOf("\n\n");
    56	      }
    57	    }
    58	  } finally {
    59	    reader.releaseLock();
    60	  }
    61	}
    62	
    63	export function CaseRunner() {
    64	  const [phase, setPhase] = useState<Phase>("idle");
    65	  const [prompt, setPrompt] = useState("");
    66	  const [entries, setEntries] = useState<TimelineEntry[]>([]);
    67	  const [pending, setPending] = useState<ResolvedPending | null>(null);
    68	  const [deciding, setDeciding] = useState(false);
    69	  const [receipt, setReceipt] = useState<CaseReceipt | null>(null);
    70	  const [error, setError] = useState<string | null>(null);
    71	
    72	  // Tool names and arguments live on the model.message that requested the
    73	  // call; the pause event only carries ids. Keep both keyed for resolution.
    74	  const toolCallsBySourceEvent = useRef(new Map<string, TrueForgeApi.ToolCall[]>());
    75	  const sessionIdRef = useRef<string | null>(null);
    76	  const activeStream = useRef<AbortController | null>(null);
    77	  // A turn can end with no output of its own — after a denial, most of all —
    78	  // so the last thing the agent said stands in as the receipt.
    79	  const narration = useRef("");
    80	
    81	  const handleEvent = useCallback((event: StreamEvent) => {
    82	    if ("type" in event && event.type === "case.started") {
    83	      sessionIdRef.current = event.sessionId;
    84	      return;
    85	    }
    86	    if ("type" in event && event.type === "stream.error") {
    87	      setError(event.error);
    88	      setPhase("error");
    89	      return;
    90	    }
    91	
    92	    if (event.type === "model.message") {
    93	      if (event.toolCalls) {
    94	        toolCallsBySourceEvent.current.set(event.id, event.toolCalls);
    95	      }
    96	      const text = contentToText(event.content);
    97	      if (text) {
    98	        narration.current = text;
    99	      }
   100	    }
   101	    setEntries((current) => applyTimelineEvent(current, event));
   102	
   103	    if (event.type === "tool.approval_required") {
   104	      const approval = extractApproval(event);
   105	      if (approval) {
   106	        const calls = approval.sourceEventId
   107	          ? toolCallsBySourceEvent.current.get(approval.sourceEventId)
   108	          : undefined;
   109	        const call = calls?.find((candidate) => candidate.id === approval.toolCallId);
   110	        setPending({ ...approval, ...(call ? describeToolCall(call) : {}) });
   111	        setPhase("awaiting");
   112	      }
   113	      return;
   114	    }
   115	
   116	    if (event.type === "turn.done") {
   117	      // A paused turn still reports done, listing the decision it is waiting
   118	      // on. Closing the case here would retire the approval card in the same
   119	      // render it was raised in, and the gate would never be seen.
   120	      if (pendingActions(event).length > 0) {
   121	        return;
   122	      }
   123	      setPending(null);
   124	      setReceipt(buildReceipt(event, narration.current));
   125	      setPhase("done");
   126	    }
   127	  }, []);
   128	
   129	  const startCase = useCallback(async () => {
   130	    const trimmed = prompt.trim();
   131	    if (!trimmed) {
   132	      return;
   133	    }
   134	    setEntries([]);
   135	    setPending(null);
   136	    setReceipt(null);
   137	    setError(null);
   138	    setPhase("running");
   139	    toolCallsBySourceEvent.current.clear();
   140	    narration.current = "";
   141	
   142	    const controller = new AbortController();
   143	    activeStream.current = controller;
   144	    try {
   145	      await consumeSse(
   146	        await fetch("/api/case", {
   147	          method: "POST",
   148	          headers: { "content-type": "application/json" },
   149	          body: JSON.stringify({ prompt: trimmed }),
   150	          signal: controller.signal,
   151	        }),
   152	        handleEvent,
   153	      );
   154	    } catch (streamError) {
   155	      if (!controller.signal.aborted) {
   156	        setError(streamError instanceof Error ? streamError.message : String(streamError));
   157	        setPhase("error");
   158	      }
   159	    } finally {
   160	      if (activeStream.current === controller) {
   161	        activeStream.current = null;
   162	      }
   163	    }
   164	  }, [handleEvent, prompt]);
   165	
   166	  const decide = useCallback(
   167	    async (decision: { status: "allow" | "deny"; reason?: string }) => {
   168	      const sessionId = sessionIdRef.current;
   169	      if (!sessionId || !pending) {
   170	        return;
   171	      }
   172	      const controller = new AbortController();
   173	      activeStream.current = controller;
   174	      setDeciding(true);
   175	      // This decision is spent. The resumed turn raises its own card if it
   176	      // pauses again, and a case that reaches a pull request pauses at every
   177	      // write along the way.
   178	      setPending(null);
   179	      setPhase("running");
   180	      try {
   181	        await consumeSse(
   182	          await fetch(`/api/case/${sessionId}/approve`, {
   183	            method: "POST",
   184	            headers: { "content-type": "application/json" },
   185	            body: JSON.stringify({
   186	              threadId: pending.threadId,
   187	              toolCallId: pending.toolCallId,
   188	              ...decision,
   189	            }),
   190	            signal: controller.signal,
   191	          }),
   192	          handleEvent,
   193	        );
   194	      } catch (streamError) {
   195	        if (!controller.signal.aborted) {
   196	          setError(streamError instanceof Error ? streamError.message : String(streamError));
   197	          setPhase("error");
   198	        }
   199	      } finally {
   200	        setDeciding(false);
   201	        if (activeStream.current === controller) {
   202	          activeStream.current = null;
   203	        }
   204	      }
   205	    },
   206	    [handleEvent, pending],
   207	  );
   208	
   209	  const stageEntries = (stage: (typeof STAGES)[number]) =>
   210	    entries.filter((entry) => entry.stage === stage);
   211	  const rawEntries = entries.filter((entry) => entry.stage === null && entry.kind === "event");
   212	
   213	  return (
   214	    <div className="mt-10">
   215	      <form
   216	        onSubmit={(event) => {
   217	          event.preventDefault();
   218	          void startCase();
   219	        }}
   220	        className="flex gap-2"
   221	      >
   222	        <input
   223	          type="text"
   224	          value={prompt}
   225	          onChange={(event) => setPrompt(event.target.value)}
   226	          placeholder="Describe the production failure…"
   227	          className="flex-1 rounded-md border border-neutral-300 px-3 py-2 text-sm dark:border-neutral-700 dark:bg-neutral-900"
   228	        />
   229	        <button
   230	          type="submit"
   231	          disabled={phase === "running" || phase === "awaiting"}
   232	          className="rounded-md bg-neutral-900 px-4 py-2 text-sm font-medium text-white hover:bg-neutral-700 disabled:opacity-50 dark:bg-white dark:text-neutral-900 dark:hover:bg-neutral-200"
   233	        >
   234	          Open case
   235	        </button>
   236	      </form>
   237	
   238	      {phase !== "idle" ? (
   239	        <ol className="mt-8 space-y-6">
   240	          {STAGES.map((stage) => {
   241	            const stageOwn = stageEntries(stage);
   242	            return (
   243	              <li
   244	                key={stage}
   245	                className="border-l-2 border-neutral-200 pl-4 dark:border-neutral-800"
   246	              >
   247	                <h2 className="text-sm font-semibold tracking-wide text-neutral-500 uppercase">
   248	                  {stage}
   249	                </h2>
   250	                {stageOwn.length > 0 ? (
   251	                  <ul className="mt-2 space-y-2">
   252	                    {stageOwn.map((entry) => (
   253	                      <li key={entry.key} className="text-sm">
   254	                        <span className="font-mono text-xs text-neutral-400">{entry.title}</span>
   255	                      </li>
   256	                    ))}
   257	                  </ul>
   258	                ) : (
   259	                  <p className="mt-1 text-sm text-neutral-400">—</p>
   260	                )}
   261	                {stage === "Approval" && pending ? (
   262	                  <div className="mt-2">
   263	                    <ApprovalCard
   264	                      pending={pending}
   265	                      busy={deciding}
   266	                      onDecide={(decision) => void decide(decision)}
   267	                    />
   268	                  </div>
   269	                ) : null}
   270	                {stage === "Receipt" && receipt ? (
   271	                  <div className="mt-2 rounded-lg border border-neutral-200 p-3 dark:border-neutral-800">
   272	                    <p className="text-sm whitespace-pre-wrap">{receipt.text}</p>
   273	                    {receipt.links.map((link) => (
   274	                      <a
   275	                        key={link}
   276	                        href={link}
   277	                        className="mt-1 block text-sm text-sky-600 underline dark:text-sky-400"
   278	                      >
   279	                        {link}
   280	                      </a>
   281	                    ))}
   282	                  </div>
   283	                ) : null}
   284	              </li>
   285	            );
   286	          })}
   287	        </ol>
   288	      ) : null}
   289	
   290	      {rawEntries.length > 0 ? (
   291	        <details className="mt-8">
   292	          <summary className="cursor-pointer text-sm font-medium text-neutral-500">
   293	            Raw events ({rawEntries.length})
   294	          </summary>
   295	          <ul className="mt-2 space-y-1">
   296	            {rawEntries.map((entry) => (
   297	              <li key={entry.key} className="font-mono text-xs text-neutral-400">
   298	                {entry.title}
   299	              </li>
   300	            ))}
   301	          </ul>
   302	        </details>
   303	      ) : null}
   304	
   305	      {entries.some((entry) => entry.kind === "message" && entry.text) ? (
